import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
class ExerciseTest {
@Test void originalCases() {
    assertThat(Calc.run("1 + 1")).as("source case 1").isEqualTo(2);
    assertThat(Calc.run("2 + 1")).as("source case 2").isEqualTo(3);
    assertThat(Calc.run("2 + 2")).as("source case 3").isEqualTo(4);
    assertThat(Calc.run("1000 + 280")).as("source case 4").isEqualTo(1280);
    assertThat(Calc.run("2 - 1")).as("source case 5").isEqualTo(1);
    assertThat(Calc.run("3 - 1")).as("source case 6").isEqualTo(2);
    assertThat(Calc.run("100 - 20")).as("source case 7").isEqualTo(80);
    assertThat(Calc.run("10 + 20 + 30")).as("source case 8").isEqualTo(60);
    assertThat(Calc.run("10 - 20 + 30")).as("source case 9").isEqualTo(20);
    assertThat(Calc.run("10 - 10 - 10 - 10")).as("source case 10").isEqualTo(-20);
    assertThat(Calc.run("10 - 10 - 10 - 10 + 10 + 10 - 10")).as("source case 11").isEqualTo(-10);
}

}

